SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, SUM(CASE WHEN e.charttime BETWEEN a.intime AND a.intime + INTERVAL '12 hours' THEN 1 ELSE 0 END) AS insulin_first_12_hours, SUM(CASE WHEN e.charttime BETWEEN (a.outtime - INTERVAL '48 hours') AND a.outtime THEN 1 ELSE 0 END) AS oral_agent_final_48_hours, (insulin_first_12_hours - oral_agent_final_48_hours) AS net_change FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN chartevents e ON a.subject_id = e.subject_id AND a.hadm_id = e.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 54 AND 64 AND d.icd_code IN ('440.0', '440.1') GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version;